import pypdf, re
files = {
 "01_irie2010_diarylethene_pjab.pdf": ["half-life","years","fatigue","10 5","10 4","cycles"],
 "06_kobe_spiropyran_silica.pdf": ["half","SPOH","SPCOOH","silica","life"],
 "10_weinstain2020_release_review.pdf": ["two-step","sequential","AND","order"],
}
for f, kws in files.items():
    try:
        r = pypdf.PdfReader(f)
        if r.is_encrypted:
            r.decrypt("")
        n = len(r.pages)
        t0 = re.sub(r"\s+"," ",(r.pages[0].extract_text() or ""))[:200]
        print(f"\n### {f} | pages={n}\nP1: {t0}")
        full = "".join((p.extract_text() or "")+"\n" for p in r.pages[:8])
        low = full.lower()
        for kw in kws:
            i = low.find(kw.lower())
            if i>=0:
                print(f"  [{kw}] ...{re.sub(chr(92)+'s+',' ',full[max(0,i-90):i+160])}...")
            else:
                print(f"  [{kw}] --")
    except Exception as e:
        print(f"\n### {f} ERROR {type(e).__name__}: {e}")
EOF

